# collect keys from base strings.xml and plurals.xml that are extension-related
def keys_of(path):
    txt=open(path,encoding='utf-8').read()
    return set(re.findall(r'<(?:string|plurals)\s+name="([^"]+)"',txt))
base_keys=set()
for f in glob.glob(base_dir+"/base/*.xml"):
    base_keys|=keys_of(f)
ext_re=re.compile(r'^(ext_|extension|extensionStores|untrusted_extension|obsolete_extension|remove_private_extension|label_extension)',re.I)
ext_keys={k for k in base_keys if ext_re.match(k)}
