print()
print("LOCALES WITH AT LEAST ONE EXT KEY:")
for d in sorted(os.listdir(base_dir)):
    p=os.path.join(base_dir,d)
    if not os.path.isdir(p) or d=="base": continue
    found=set()
    for f in glob.glob(p+"/*.xml"):
